const assert = require('assert');
const ts = require('./build/mathutils.js');
const js = require('./mathutils.js');
// identical behavior to the JS original, spot-checked against it
for (const values of [[], [4], [1, 2, 3, 4]]) {
  assert.strictEqual(ts.mean(values), js.mean(values), `mean(${JSON.stringify(values)})`);
}
assert.strictEqual(ts.clamp(-5, 0, 10), 0);
assert.strictEqual(ts.clamp(15, 0, 10), 10);
assert.strictEqual(ts.clamp(5, 0, 10), 5);
assert.deepStrictEqual(ts.range(0, 5), [0, 1, 2, 3, 4], 'default step must be 1');
assert.deepStrictEqual(ts.range(0, 10, 3), [0, 3, 6, 9]);
assert.deepStrictEqual(ts.range(3, 3), []);
console.log('PASS');

